/**
 * theme.json -> src/ui/theme.ts + src/ui/theme.css (DR-088).
 *
 * theme.json is the only place a colour literal may live. Code reads the
 * generated semantic tokens. Run with `node tools/gen-theme.ts` to rewrite the
 * generated files, or with `--check` to fail when they are stale.
 *
 * Stage 0 generated the colour, font and logical-size tokens. Stage 4 adds the
 * rest: type, touch, layout, shape, motion and focus (semantic), the spacing
 * scales (primitive) and every component token, with `{ref}`s resolved.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export interface ThemeJson {
  meta: {
    logical: { width: number; height: number };
    contrastRule: { text: number; nonText: number };
  };
  primitive: {
    color: Record<string, string>;
    space: Record<string, number>;
    radius: Record<string, number>;
    outline: Record<string, number>;
    shadowY: Record<string, number>;
    font: {
      display: { family: string };
      body: { family: string };
      fallback: string;
    };
  };
  semantic: {
    color: Record<string, string | { color: string; alpha: number }>;
    onColor: Record<string, string | { text: string; ratio: number }>;
    [group: string]: unknown;
  };
  component: Record<string, unknown>;
}

/** Semantic groups that are not colours; they go to `tokens` in theme.ts. */
export const SEMANTIC_GROUPS = ['type', 'touch', 'layout', 'shape', 'motion', 'focus'] as const;
/** Primitive scales that component tokens may reference by field name. */
const SCALE_FIELDS = ['radius', 'outline', 'shadowY'] as const;

export interface ResolvedColor {
  /** Upper-case #RRGGBB. */
  hex: string;
  /** 0..1. Only the scrim is below 1. */
  alpha: number;
}

const HEADER = 'GENERATED by tools/gen-theme.ts from src/ui/theme.json. Do not edit.';

function resolveRef(theme: ThemeJson, ref: string, where: string): string {
  const m = /^\{([a-z0-9-]+)\}$/.exec(ref);
  if (!m?.[1]) throw new Error(`${where}: "${ref}" is not a {primitive} reference`);
  const hex = theme.primitive.color[m[1]];
  if (!hex || !/^#[0-9A-Fa-f]{6}$/.test(hex)) {
    throw new Error(`${where}: unknown primitive colour "${m[1]}"`);
  }
  return hex.toUpperCase();
}

/** Semantic colour name -> resolved hex and alpha, in theme.json order. */
export function resolveSemanticColors(theme: ThemeJson): Record<string, ResolvedColor> {
  const out: Record<string, ResolvedColor> = {};
  for (const [name, value] of Object.entries(theme.semantic.color)) {
    if (name.startsWith('_')) continue;
    if (typeof value === 'string') {
      out[name] = { hex: resolveRef(theme, value, `semantic.color.${name}`), alpha: 1 };
    } else {
      out[name] = {
        hex: resolveRef(theme, value.color, `semantic.color.${name}`),
        alpha: value.alpha,
      };
    }
  }
  return out;
}

/** Fill name -> the one text colour allowed on it (DR-080). */
export function resolveOnColors(theme: ThemeJson): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [name, value] of Object.entries(theme.semantic.onColor)) {
    if (name.startsWith('_') || typeof value === 'string') continue;
    out[name] = resolveRef(theme, value.text, `semantic.onColor.${name}`);
  }
  return out;
}

/** The semantic colour name whose value is primitive colour `name`. */
function semanticNameOf(theme: ThemeJson, primitive: string, where: string): string {
  const want = `{${primitive}}`;
  for (const [name, value] of Object.entries(theme.semantic.color)) {
    if (name.startsWith('_')) continue;
    if (value === want) return name;
  }
  throw new Error(`${where}: primitive colour "${primitive}" has no semantic name`);
}

/**
 * Resolves the `{ref}` strings inside a token tree:
 *   - under a `radius`, `outline` or `shadowY` key, `{x}` is that primitive scale's x
 *   - `{colour}` becomes the semantic colour name for that primitive colour
 * Keys starting with `_` are notes and are dropped.
 */
export function resolveTokens(theme: ThemeJson, value: unknown, where: string, key = ''): unknown {
  if (typeof value === 'string') {
    const m = /^\{([a-z0-9-]+)\}$/.exec(value);
    if (!m?.[1]) return value;
    const ref = m[1];
    const scaleKey = SCALE_FIELDS.find((k) => k === key);
    if (scaleKey) {
      const v = theme.primitive[scaleKey][ref];
      if (v === undefined) throw new Error(`${where}: unknown ${scaleKey} "${ref}"`);
      return v;
    }
    if (ref in theme.primitive.color) return semanticNameOf(theme, ref, where);
    throw new Error(`${where}: cannot resolve "${value}"`);
  }
  if (Array.isArray(value)) return value.map((v, i) => resolveTokens(theme, v, `${where}[${i}]`));
  if (value && typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value)) {
      if (k.startsWith('_')) continue;
      out[k] = resolveTokens(theme, v, `${where}.${k}`, k);
    }
    return out;
  }
  return value;
}

/** Everything that is not a colour or a font, resolved, for `tokens` in theme.ts. */
export function buildTokens(theme: ThemeJson): Record<string, unknown> {
  const semantic: Record<string, unknown> = {};
  for (const g of SEMANTIC_GROUPS) {
    if (!(g in theme.semantic)) throw new Error(`theme.json: semantic.${g} is missing`);
    semantic[g] = resolveTokens(theme, theme.semantic[g], `semantic.${g}`);
  }
  return {
    space: theme.primitive.space,
    radius: theme.primitive.radius,
    outline: theme.primitive.outline,
    shadowY: theme.primitive.shadowY,
    ...semantic,
    component: resolveTokens(theme, theme.component, 'component'),
  };
}

function fontStack(family: string, fallback: string): string {
  return `"${family}", ${fallback}`;
}

function rgbTriplet(hex: string): string {
  const n = Number.parseInt(hex.slice(1), 16);
  return `${(n >> 16) & 255} ${(n >> 8) & 255} ${n & 255}`;
}

/** The `:root { --token: value; }` block shared by theme.css and index.html. */
export function buildThemeCss(theme: ThemeJson): string {
  const lines: string[] = [':root {'];
  for (const [name, c] of Object.entries(resolveSemanticColors(theme))) {
    lines.push(
      c.alpha === 1
        ? `  --${name}: ${c.hex};`
        : `  --${name}: rgb(${rgbTriplet(c.hex)} / ${c.alpha});`,
    );
  }
  for (const [name, hex] of Object.entries(resolveOnColors(theme))) {
    lines.push(`  --on-${name}: ${hex};`);
  }
  const font = theme.primitive.font;
  lines.push(`  --font-display: ${fontStack(font.display.family, font.fallback)};`);
  lines.push(`  --font-body: ${fontStack(font.body.family, font.fallback)};`);
  lines.push('}');
  return lines.join('\n');
}

export function buildThemeCssFile(theme: ThemeJson): string {
  return `/* ${HEADER} */\n${buildThemeCss(theme)}\n`;
}

export function buildThemeTs(theme: ThemeJson): string {
  const colors = resolveSemanticColors(theme);
  const onColors = resolveOnColors(theme);
  const num = (hex: string) => `0x${hex.slice(1).toLowerCase()}`;
  const block = (entries: [string, string][]) =>
    entries.map(([k, v]) => `  '${k}': ${v},`).join('\n');
  const font = theme.primitive.font;
  return `// ${HEADER}

/** Logical canvas size (DR-013). */
export const logical = { width: ${theme.meta.logical.width}, height: ${theme.meta.logical.height} } as const;

/** Semantic colours as 0xRRGGBB, for Phaser tints and fills. */
export const color = {
${block(Object.entries(colors).map(([k, c]) => [k, num(c.hex)]))}
} as const;

/** Semantic colours as #RRGGBB strings, for canvas 2D, Phaser Text and config. */
export const cssColor = {
${block(Object.entries(colors).map(([k, c]) => [k, `'${c.hex}'`]))}
} as const;

/** Alpha of the semantic colours that are not opaque. */
export const alpha = {
${block(
  Object.entries(colors)
    .filter(([, c]) => c.alpha !== 1)
    .map(([k, c]) => [k, String(c.alpha)]),
)}
} as const;

/** The one text colour allowed on each fill (DR-080), as 0xRRGGBB. */
export const onColor = {
${block(Object.entries(onColors).map(([k, hex]) => [k, num(hex)]))}
} as const;

/** The same text colours as #RRGGBB strings. */
export const cssOnColor = {
${block(Object.entries(onColors).map(([k, hex]) => [k, `'${hex}'`]))}
} as const;

/** Font families (DR-081). Self-hosted woff2 (J27). */
export const font = {
  display: '${font.display.family}',
  body: '${font.body.family}',
  fallback: '${font.fallback}',
} as const;

/** Sizes, motion, focus and component tokens (DR-081 to DR-086, UI.md §2), refs resolved. */
export const tokens = ${JSON.stringify(buildTokens(theme), null, 2)} as const;

export type ColorToken = keyof typeof color;
`;
}

export const paths = {
  json: fileURLToPath(new URL('../src/ui/theme.json', import.meta.url)),
  ts: fileURLToPath(new URL('../src/ui/theme.ts', import.meta.url)),
  css: fileURLToPath(new URL('../src/ui/theme.css', import.meta.url)),
};

export function loadTheme(): ThemeJson {
  return JSON.parse(readFileSync(paths.json, 'utf8')) as ThemeJson;
}

function main(): void {
  const theme = loadTheme();
  const outputs: [string, string][] = [
    [paths.ts, buildThemeTs(theme)],
    [paths.css, buildThemeCssFile(theme)],
  ];
  if (process.argv.includes('--check')) {
    const stale = outputs.filter(([file, text]) => {
      try {
        return readFileSync(file, 'utf8') !== text;
      } catch {
        return true;
      }
    });
    if (stale.length > 0) {
      console.error(`Stale generated theme files: ${stale.map(([f]) => f).join(', ')}`);
      console.error('Run: node tools/gen-theme.ts');
      process.exit(1);
    }
    return;
  }
  for (const [file, text] of outputs) writeFileSync(file, text);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main();
